#!/bin/bash
cd ~/antistudy || (mkdir -p ~/antistudy && cd ~/antistudy)
mkdir -p frontend uploads/assets data

python3 -c "import base64, gzip, tarfile, io; data = base64.b64decode(''); tarfile.open(fileobj=io.BytesIO(data), mode='r:gz').extractall('.')" 2>/dev/null || (echo '' | base64 -d | tar -xz)

pm2 delete antistudy 2>/dev/null || true
pm2 start server_pure.js --name antistudy
pm2 save
echo '🎉 恭喜！服务器已秒级更新完毕！'
